{"implementation":"def solve(case):
    """Allocate an exact bounded budget across ordered segments."""

    def _require_mapping(value, label):
        if not isinstance(value, dict):
            raise ValueError(label + " must be an object")
        return value

    def _require_int(value, label):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(label + " must be an integer")
        return value

    root = _require_mapping(case, "case")
    payload = root.get("payload", root)
    payload = _require_mapping(payload, "payload")

    if "segments" not in payload:
        raise ValueError("payload.segments is required")
    if "budget" not in payload:
        raise ValueError("payload.budget is required")

    segments_in = payload["segments"]
    if not isinstance(segments_in, list) or not segments_in:
        raise ValueError("payload.segments must be a non-empty list")

    budget = _require_int(payload["budget"], "payload.budget")
    if budget < 0:
        raise ValueError("payload.budget must be non-negative")

    segments = []
    seen_names = set()
    for index, raw in enumerate(segments_in):
        seg = _require_mapping(raw, "segment")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in seg:
                raise ValueError("segment." + field + " is required")

        name = seg["name"]
        if not isinstance(name, str) or name == "":
            raise ValueError("segment.name must be a non-empty string")
        if name in seen_names:
            raise ValueError("segment.name values must be unique")
        seen_names.add(name)

        importance = _require_int(seg["importance"], "segment.importance")
        minimum = _require_int(seg["minimum"], "segment.minimum")
        capacity = _require_int(seg["capacity"], "segment.capacity")

        if importance < 0:
            raise ValueError("segment.importance must be non-negative")
        if minimum < 0:
            raise ValueError("segment.minimum must be non-negative")
        if capacity < 0:
            raise ValueError("segment.capacity must be non-negative")
        if minimum > capacity:
            raise ValueError("segment.minimum cannot exceed segment.capacity")

        segments.append({
            "index": index,
            "name": name,
            "importance": importance,
            "minimum": minimum,
            "capacity": capacity,
        })

    minimum_total = sum(seg["minimum"] for seg in segments)
    capacity_total = sum(seg["capacity"] for seg in segments)
    if budget < minimum_total:
        raise ValueError("budget is below the sum of minimum quotas")
    if budget > capacity_total:
        raise ValueError("budget exceeds total segment capacity")

    allocated = [seg["minimum"] for seg in segments]
    remaining = budget - minimum_total

    while remaining > 0:
        best_index = None
        best_num = None
        best_den = None

        for index, seg in enumerate(segments):
            if allocated[index] >= seg["capacity"]:
                continue
            num = seg["importance"]
            den = allocated[index] + 1
            if best_index is None or num * best_den > best_num * den:
                best_index = index
                best_num = num
                best_den = den

        if best_index is None:
            raise ValueError("budget cannot be allocated within capacities")

        allocated[best_index] += 1
        remaining -= 1

    allocations = []
    for index, seg in enumerate(segments):
        allocations.append({
            "index": seg["index"],
            "name": seg["name"],
            "tokens": allocated[index],
        })

    name_mapping = {}
    for item in allocations:
        name_mapping[item["name"]] = item["tokens"]

    conserved_total = sum(item["tokens"] for item in allocations)
    if conserved_total != budget:
        raise ValueError("allocation failed to conserve the requested budget")

    return {
        "allocations": allocations,
        "name_mapping": name_mapping,
        "conserved_total": conserved_total,
    }
"}
